WA, CV, YV, WW, ID = "Washington", "Columbia Valley", "Yakima Valley", "Walla Walla Valley", "Idaho"
regions = [
 region("us", WA, 46.6, -120.2, 6.6,
 "Desert vineyards on ice-age flood soils, irrigated by the Columbia: America's second-largest wine state.",
 "Washington is the second-largest wine producer in the United States, with more than 1,000 wineries and about 60,000 acres of vines, nearly all east of the Cascade Mountains. The Cascades block Pacific storms, leaving the Columbia Basin a semi-desert with 150 to 250 mm of rain a year, hot summer days, cold nights and, at 46 degrees north, around 17 hours of summer daylight. Irrigation from the Columbia, Yakima and Snake rivers makes viticulture possible.\n\nWith the Columbia Hills AVA (2026), Washington has 22 AVAs, almost all inside the vast Columbia Valley. The big, consistent style (deep colour, ripe fruit and fresh acidity) suits Cabernet Sauvignon, Merlot and Syrah, and Riesling made the state's name in the 1970s and 1980s.",
 "Vines arrived with the Hudson's Bay Company at Fort Vancouver around 1825, and Italian and German immigrants planted in the Walla Walla and Yakima valleys in the late 19th century. After Prohibition, the industry made sweet fortified wine from Concord and other grapes. The modern era began with Associated Vintners, founded by a group of University of Washington professors led by Lloyd Woodburne (first commercial vintage 1967), and with the American Wine Growers company that became Chateau Ste. Michelle, which hired André Tchelistcheff as a consultant in 1967. Leonetti (1977), Woodward Canyon (1981) and L'Ecole No 41 (1983) put Walla Walla on the map; Quilceda Creek's Cabernets earned perfect scores in the 2000s.",
 "Between about 15,000 and 13,000 years ago the Missoula Floods repeatedly burst from glacial Lake Missoula in Montana and scoured eastern Washington, depositing sand, silt and gravel over Columbia River basalt. Wind then piled up fine loess. These sandy, low-organic soils are hostile to phylloxera, so most Washington vines are planted on their own roots, unusual among major wine regions. The trade-off is winter freezes: severe cold events (1996, 2004, 2024) can kill vines to the ground, and growers bury graft unions or rely on own-rooted vines that can regrow from below the soil.",
 "Cabernet Sauvignon, Merlot, Syrah, Chardonnay, Riesling, Cabernet Franc, Malbec, Sauvignon Blanc, Grenache.",
 "Structured Cabernet and Bordeaux blends; plush Merlot; savoury Syrah; off-dry and dry Riesling.",
 "Federal AVA rules (85 percent), but Washington requires 95 percent from the AVA for wines labeled with one. Washington has 22 AVAs, including those shared with Oregon and Idaho.",
 ["Columbia Valley", "Yakima Valley", "Red Mountain", "Walla Walla Valley", "Horse Heaven Hills", "Wahluke Slope", "Ancient Lakes of Columbia Valley", "Lake Chelan", "Puget Sound", "Columbia Gorge", "Lewis-Clark Valley"], SRC, parent=None),
 region("us", CV, 46.4, -119.6, 7.0,
 "A semi-desert basin of 11 million acres that contains almost all of Washington's vines.",
 "Columbia Valley (1984, realigned 2001 and 2016) covers about a quarter of Washington plus a slice of Oregon. It is the basin drained by the Columbia, Yakima and Snake rivers, ringed by the Cascades and the Blue Mountains. Rainfall is low, summers hot, winters cold, and nearly every vineyard is irrigated. Most Washington wines carry Columbia Valley or one of its 19 sub-AVAs.",
 "See Washington. The largest producers (Chateau Ste. Michelle, Columbia Crest) blend from across the valley.",
 "Missoula flood gravels and sands, wind-blown loess, Columbia River basalt; low rainfall, long, sunny days and cold nights.",
 "Cabernet Sauvignon, Merlot, Syrah, Chardonnay, Riesling.", "Ripe, balanced reds and fresh whites.",
 "Columbia Valley contains most Washington AVAs.",
 ["Columbia Valley", "Yakima Valley", "Red Mountain", "Rattlesnake Hills", "Snipes Mountain", "Candy Mountain", "Goose Gap", "Horse Heaven Hills", "Wahluke Slope", "Royal Slope", "Beverly, Washington", "Ancient Lakes of Columbia Valley", "White Bluffs", "Naches Heights", "Lake Chelan", "Rocky Reach", "The Burn of Columbia Valley", "Columbia Hills", "Walla Walla Valley"], SRC, parent=WA),
 region("us", ID, 43.6, -116.6, 7.6,
 "High-desert vineyards along the Snake River, at some of the highest elevations in the Northwest.",
 "Idaho has around 70 wineries and a few thousand acres of vines, mostly in the Snake River Valley west of Boise, at elevations of roughly 600 to 900 m. Hot days, cold nights and volcanic and lake-bed soils give fresh Riesling, Syrah, Tempranillo and Cabernet. Cold winters are the main risk. The Lewis-Clark Valley on the Idaho-Washington border, at a much lower elevation, was a thriving wine region before Prohibition.",
 "French and German settlers planted vines around Lewiston from the 1860s, and the Lewis-Clark area was the centre of a small pre-Prohibition industry. Statewide prohibition, which Idaho adopted in 1916, ended it. Ste. Chapelle (1975) led the revival.",
 "Lake Idaho sediments and volcanic soils in the Snake River Plain; wide temperature swings.",
 "Riesling, Syrah, Chardonnay, Cabernet Sauvignon, Merlot, Tempranillo, Malbec.",
 "Aromatic whites and fresh, high-elevation reds.",
 "Three AVAs: Snake River Valley (shared with Oregon), Eagle Foothills, Lewis-Clark Valley (shared with Washington).",
 ["Snake River Valley", "Eagle Foothills", "Lewis-Clark Valley"], SRC, parent=None)]

A = []
A.append(ava("Columbia Valley", CV, "Washington's giant umbrella AVA (1984) of about 11.5 million acres covering most of eastern Washington and a strip of northern Oregon. Low rainfall, long sunny days, cold nights and Missoula flood soils give wines of ripe fruit and fresh acidity. Most Washington wine, including the biggest brands, carries this name. Inside it are 19 sub-AVAs.", sub="Washington and Oregon", styles=["red", "white", "sweet"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Chardonnay, Riesling, Cabernet Franc", producers=["Chateau Ste. Michelle", "Columbia Crest", "Quilceda Creek (sources)", "L'Ecole No 41", "Andrew Will", "Gramercy Cellars"], contains=["Yakima Valley", "Walla Walla Valley", "Horse Heaven Hills", "Wahluke Slope", "Ancient Lakes of Columbia Valley", "Lake Chelan", "Naches Heights", "Royal Slope", "White Bluffs", "Rocky Reach", "The Burn of Columbia Valley", "Beverly, Washington", "Columbia Hills"]))
A.append(ava("Yakima Valley", YV, "Washington's first AVA (1983), along the Yakima River from Union Gap to near the Tri-Cities. It is the historical centre of Washington grape growing: Concord for juice, then wine grapes from the 1960s. Today about a third of the state's wine grapes grow here. The west end is cooler, the east end warmer; famous vineyards include Red Willow (planted 1973, an early source of Syrah) and Boushey.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Chardonnay, Riesling", producers=["Columbia Winery (Red Willow)", "Owen Roe", "Cote Bonneville", "Boushey (grower)", "DeLille (sourcing)"], contains=["Red Mountain", "Rattlesnake Hills", "Snipes Mountain", "Candy Mountain", "Goose Gap"]))
A.append(ava("Red Mountain", YV, "Washington's smallest AVA from 2001 until Candy Mountain arrived in 2020, about 4,000 acres on the southwest-facing slope of a low ridge near Benton City, at the east end of the Yakima Valley. It is one of the warmest spots in the state, with constant wind and very low rainfall; sandy, calcareous, rocky soils and wind stress produce small berries with thick skins.\n\nThe result is Washington's most tannic, concentrated Cabernet Sauvignon. Jim Holmes and John Williams planted Kiona and Ciel du Cheval in 1975; Hedges, Col Solare (Ste. Michelle and Antinori), Klipsun and Tapteil followed.", sub="Yakima Valley", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Cabernet Franc, Petit Verdot", producers=["Hedges", "Col Solare", "Kiona", "Fidélitas", "Cadence", "Quilceda Creek (Galitzine Vineyard)"], nerd="Despite the name, the mountain is not red; it is named for the cheatgrass (downy brome) that turns the slopes reddish in spring."))
A.append(ava("Rattlesnake Hills", YV, "A sub-AVA (2006) of about 68,500 acres on the south-facing slopes of the Rattlesnake Hills north of the Yakima River, at 260 to 900 m, with many small wineries. Higher elevation and good air drainage reduce frost risk.", sub="Yakima Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Riesling"))
A.append(ava("Snipes Mountain", YV, "A small AVA (2009) of 4,145 acres on a single uplift rising from the floor of the Yakima Valley near Sunnyside. Its rocky soils include rounded cobbles carried by the ancestral Columbia River. William B. Bridgman planted vinifera on its slopes around 1917 and founded Upland Winery in 1934, and Harrison Hill Vineyard has Cabernet Sauvignon planted in 1963, among the oldest in the state. Named for cattle baron Ben Snipes, who settled at its base in the 1850s.", sub="Yakima Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Muscat, Syrah", producers=["Upland Estates", "Harrison Hill (DeLille)"]))
A.append(ava("Candy Mountain", YV, "One of Washington's smallest AVAs (2020), about 815 acres on the southwest-facing slope of Candy Mountain near Richland, close to Red Mountain. Steep slopes, shallow loess and wind give dense Cabernet. TTB modified the Yakima Valley boundary to include it.", sub="Yakima Valley", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Syrah, Merlot"))
A.append(ava("Goose Gap", YV, "A small AVA (2021) of about 8,129 acres in the hills south of Red Mountain near Richland. At approval it had two vineyards covering more than 1,800 acres and one winery; the petition stressed geology and soils on the hill's folded basalt.", sub="Yakima Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay"))
A.append(ava("Horse Heaven Hills", CV, "A big AVA (2005) of about 570,000 acres on the south-facing slopes above the Columbia River, south of the Yakima Valley. Steady wind from the river reduces frost and disease. Champoux Vineyard (planted 1972 as Mercer Ranch) has given perfect-score Cabernets to Quilceda Creek and Andrew Will; Columbia Crest is based here. At approval there were 6,040 acres of vines.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Chardonnay, Riesling", producers=["Columbia Crest", "Champoux (grower)", "Andrew Will", "Mercer Estates", "Double Canyon"]))
A.append(ava("Wahluke Slope", CV, "A broad, south-facing alluvial fan (2006) of about 81,000 acres on the north bank of the Columbia, east of Mattawa, one of the warmest and driest places in Washington. Huge vineyards supply many wineries with ripe Merlot, Cabernet and Syrah.", sub="Columbia Valley", styles=["red"], dom="red", grapes="Merlot, Cabernet Sauvignon, Syrah, Grenache", producers=["Milbrandt", "Sagemoor (sourcing)"]))
A.append(ava("Royal Slope", CV, "A large AVA (2020) of 156,389 acres on the gentle, south-facing slopes of the Frenchman Hills, north of the Wahluke Slope. At approval 13 vineyards covered about 14,100 acres, many of them very large; the elevation and slope keep cold air draining away.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Chardonnay"))
A.append(ava("Beverly, Washington", CV, "A small AVA (2024) of about 2,415 acres on terraces above the Columbia River at the hamlet of Beverly, just north of Sentinel Gap. It was proposed as 'Wanapum Village', but the petitioner asked for a new name after members of the Wanapum tribe objected to the use of their name, and TTB approved it as 'Beverly, Washington'.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Chardonnay", match=["Beverly"]))
A.append(ava("Ancient Lakes of Columbia Valley", CV, "A cool northern AVA (2012) of about 162,800 acres near Quincy, named for lakes left in coulees carved by the Missoula Floods. Caliche-rich soils and a cooler climate make it Washington's best area for crisp Riesling, Chardonnay and Pinot Gris. At approval it had 1,399 acres in six vineyards.", sub="Columbia Valley", styles=["white", "red"], dom="white", grapes="Riesling, Chardonnay, Pinot Gris, Sauvignon Blanc", producers=["Cave B", "White Heron", "Jones of Washington"]))
A.append(ava("White Bluffs", CV, "An AVA (2021) of about 93,700 acres on a plateau east of the Columbia near Pasco, named for the pale cliffs of ancient lake sediments (the Ringold Formation) along the river. The plateau's flat top and south-facing slopes are cut by the Ringold and Koontz coulees.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Riesling"))
A.append(ava("Naches Heights", CV, "A volcanic plateau (2011) of about 13,250 acres northwest of Yakima, at 365 to 640 m, formed by the Tieton andesite lava flow; its soils are wind-blown loess over that volcanic rock. At approval it had 105 acres of vines.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Syrah, Riesling, Tempranillo, Pinot Gris"))
A.append(ava("Lake Chelan", CV, "A glacial-lake AVA (2009) of about 24,000 acres around the southern end of Lake Chelan, about 80 km long and one of the deepest lakes in the United States. The lake moderates temperatures and extends the season. At approval it had 13 bonded wineries and 140 acres; Riesling, Pinot Noir, Syrah and Malbec now grow among apple orchards.", sub="Columbia Valley", styles=["white", "red"], dom="white", grapes="Riesling, Pinot Gris, Syrah, Malbec, Pinot Noir", producers=["Tsillan Cellars", "Karma", "Vin du Lac", "Benson"]))
A.append(ava("Rocky Reach", CV, "A small AVA (2022) of about 32,000 acres on terraces along the Columbia River north of Wenatchee, near the Rocky Reach Dam. Its gravelly, rocky soils were deposited when the Missoula Floods and glacial outburst floods reshaped the canyon.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Syrah, Cabernet Sauvignon, Riesling"))
A.append(ava("The Burn of Columbia Valley", CV, "An AVA (2021) of about 16,870 acres on a plateau above the Columbia River in eastern Klickitat County. The name is the one local residents have long used for the plateau; TTB declined to protect 'The Burn' on its own because the term is used elsewhere.", sub="Columbia Valley", styles=["red"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah"))
A.append(ava("Columbia Hills", CV, "Washington's 22nd AVA (effective September 2026), about 29,387 acres in Klickitat County along the north bank of the Columbia River opposite The Dalles and around Maryhill. Eighty percent of the land lies within a mile of the river, which acts as a heat reservoir; soils are coarse basalt colluvium and wind-blown sand and gravel bars left by the ice-age floods, much coarser than the loess common elsewhere. At approval there were about 338 acres of vines owned by 19 landowners and four wineries.\n\nThe name comes from the Columbia Hills Natural Area Preserve and Columbia Hills Historical State Park, home to the petroglyph 'She Who Watches'.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Syrah, Cabernet Sauvignon, Grenache, Viognier", created="2026", lat=45.705, lon=-120.80))
A.append(ava("Walla Walla Valley", WW, "A celebrated AVA (1984, realigned 2001) shared by Washington and Oregon, around the town of Walla Walla at the foot of the Blue Mountains. Rainfall rises sharply toward the mountains (from about 300 mm in the west to more than 500 mm near the foothills), so some vineyards can be dry-farmed. Soils are wind-blown loess over Missoula flood deposits, plus basalt cobbles in The Rocks District.\n\nLeonetti (1977), Woodward Canyon (1981) and L'Ecole No 41 (1983) built the valley's name for Cabernet, Merlot and Syrah; it now has well over 100 wineries. TTB proposed a Mill Creek-Walla Walla Valley sub-AVA of about 4,900 acres in August 2026.", sub="Columbia Valley", styles=["red", "white"], dom="red", grapes="Cabernet Sauvignon, Merlot, Syrah, Cabernet Franc, Grenache", producers=["Leonetti", "Woodward Canyon", "L'Ecole No 41", "Pepper Bridge", "Gramercy Cellars", "Cayuse", "Seven Hills", "Long Shadows"], contains=["The Rocks District of Milton-Freewater"]))
A.append(ava("Puget Sound", WA, "A large AVA (1995) of about 4.5 million acres west of the Cascades, around Seattle and the islands of Puget Sound. Cool, cloudy and wet, it suits early-ripening grapes such as Madeleine Angevine, Siegerrebe, Müller-Thurgau and Pinot Noir. It is home to many wineries that buy grapes from eastern Washington, so the AVA name is used on only a small share of their wines.", sub="Washington", styles=["white", "red"], dom="white", grapes="Madeleine Angevine, Siegerrebe, Müller-Thurgau, Pinot Noir, Pinot Gris", producers=["Bainbridge Vineyards", "Lopez Island Vineyards", "Spoiled Dog"]))
A.append(ava("Lewis-Clark Valley", ID, "A low, deep river canyon (2016) of about 307,000 acres where the Snake and Clearwater rivers meet at Lewiston, Idaho and Clarkston, Washington, far lower and warmer than the Snake River Valley to the south. Before Prohibition it was a thriving wine region. At approval it had 16 vineyards (81 acres) and three wineries. TTB realigned the Columbia Valley to avoid overlap.", sub="Idaho and Washington", styles=["red", "white"], dom="red", grapes="Syrah, Cabernet Sauvignon, Riesling, Merlot"))
A.append(ava("Snake River Valley", ID, "A huge AVA (2007) of about 5.2 million acres along the Snake River across southwestern Idaho and two Oregon counties. Vineyards mostly sit at 600 to 900 m on volcanic and old lake-bed soils (from Pliocene Lake Idaho), with hot days, cold nights and frequent winter freeze risk. At approval it had 15 wineries and 1,107 acres of vines.", sub="Idaho and Oregon", styles=["white", "red"], dom="red", grapes="Riesling, Chardonnay, Syrah, Cabernet Sauvignon, Tempranillo, Malbec", producers=["Ste. Chapelle", "Koenig", "Sawtooth", "Cinder", "Hells Canyon"], contains=["Eagle Foothills"]))
A.append(ava("Eagle Foothills", ID, "A sub-AVA (2015) of about 49,800 acres in the foothills north of Eagle, west of Boise, slightly higher and cooler than the surrounding Snake River Valley, with nine vineyards (67 acres) at approval. Bitner Vineyards and 3 Horse Ranch are known producers.", sub="Snake River Valley", styles=["red", "white"], dom="red", grapes="Syrah, Riesling, Cabernet Sauvignon, Pinot Gris", producers=["3 Horse Ranch", "Bitner"]))

S = []
S.append(site("ciel-du-cheval", "us", "Ciel du Cheval Vineyard", "vineyard", "Red Mountain", 46.2900, -119.4500,
 "Planted in 1975 by Jim Holmes and John Williams (who also founded Kiona), one of the first vineyards on Red Mountain. Its Cabernet, Merlot and Syrah supply a who's who of Washington wineries.", cls="Planted 1975", q="approx", producers=["Andrew Will", "DeLille", "Quilceda Creek (historically)", "Cadence"]))
S.append(site("champoux", "us", "Champoux Vineyard", "vineyard", "Horse Heaven Hills", 45.9600, -119.7500,
 "Planted in 1972 as part of Mercer Ranch and farmed by Paul Champoux from 1989. Quilceda Creek's Champoux Cabernets helped put Washington among the world's great Cabernet regions.", cls="Planted 1972", q="approx", producers=["Quilceda Creek", "Andrew Will", "Woodward Canyon"]))
S.append(site("leonetti-cellar", "us", "Leonetti Cellar", "estate", "Walla Walla Valley", 46.0559, -118.2978,
 "Gary Figgins founded Leonetti in 1977 on land his Italian grandfather farmed; its 1978 Cabernet appeared on the cover of a national wine magazine and made Walla Walla famous.", cls="Founded 1977", q="approx", producers=["Leonetti Cellar"]))
S.append(site("quilceda-creek", "us", "Quilceda Creek", "estate", "Puget Sound", 47.9500, -122.0775,
 "Alex Golitzin, nephew of André Tchelistcheff, founded Quilceda Creek in Snohomish west of the Cascades in 1979 and trucked grapes from eastern Washington. Its 2002 Cabernet was the first Washington wine to receive 100 points from The Wine Advocate.", cls="Founded 1979", q="approx", producers=["Quilceda Creek"]))
S.append(site("chateau-ste-michelle", "us", "Chateau Ste. Michelle", "estate", "Puget Sound", 47.7293, -122.1494,
 "Washington's largest and best-known winery, whose roots go back to Prohibition-era companies; the château at Woodinville near Seattle opened in 1976. Its Eroica Riesling partnership with Ernst Loosen (from 1999) helped make Washington a Riesling powerhouse.", producers=["Chateau Ste. Michelle"]))
S.append(site("red-willow", "us", "Red Willow Vineyard", "vineyard", "Yakima Valley", 46.3700, -120.5900,
 "Mike Sauer planted Red Willow in 1973 on the western edge of the Yakima Valley and, working with David Lake MW of Columbia Winery, planted some of Washington's first Syrah in the mid-1980s. A small stone chapel on the hilltop is a landmark.", q="approx", producers=["Owen Roe", "Betz", "Columbia Winery"]))
S.append(site("ste-chapelle", "us", "Ste. Chapelle", "estate", "Snake River Valley", 43.6100, -116.7700,
 "Founded in 1975 by the Symms family and named for the Gothic chapel in Paris that inspired its original building, Ste. Chapelle led the revival of Idaho wine and remains its largest producer.", cls="Founded 1975", q="approx", producers=["Ste. Chapelle"]))
save_part("p07_washington_idaho", regions=regions, appellations=A, sites=S)
